#pragma once
#include "runtime_short_kernel.hpp"
#include "compact_response_kernel.hpp"
#include "compact_phi_model.hpp"
#include "initial_kernel_candidates.hpp"
#include "selected_feature_schema.hpp"
#include "directional_terminal_bounds.hpp"
#ifndef RUNTIME_SOURCE_LOWER_PRUNE
#define RUNTIME_SOURCE_LOWER_PRUNE 1
#endif
struct KernelTrace{Node site=0;int core=-1,end=-1,entry=0,nominal=0,arc=0,kind=-1;};
class RuntimeRouteModel{
 const Graph&graph;RuntimeShortKernel short_kernel;CompactResponseKernel far_kernel,near_kernel;InitialKernelCandidates initial;CompactPhiModel phi;DirectionalTerminalBounds terminal_bounds;
 std::array<int,120>xgap{};std::array<int,550>ygap{};
 struct ForestNode{uint16_t feature,left,right,flags;double number;};static_assert(sizeof(ForestNode)==16);std::vector<std::vector<ForestNode>>forest;
public:
 RuntimeRouteModel(const Graph&g,const std::string&folder):graph(g),short_kernel({1,3,6,9}),far_kernel(folder+"/far-curves.bin"),near_kernel(folder+"/near-curves.bin"),initial(g,folder+"/source-hints.bin"),phi(folder+"/phi-patterns.bin"),terminal_bounds(initial.terminals){
  if(far_kernel.horizontal_anchors()!=std::vector<unsigned>{1,3,6,9})throw std::runtime_error("Runtime anchor mismatch");for(auto l:archdata::LINES){if(l.vertical)for(int x=l.site+1;x<120;++x)xgap[x]+=l.delay;else for(int y=l.site+1;y<550;++y)ygap[y]+=l.delay;}
  std::ifstream f(folder+"/correction.bin",std::ios::binary);std::array<char,144>h;f.read(h.data(),h.size());uint32_t nf,nt;std::memcpy(&nf,h.data()+136,4);std::memcpy(&nt,h.data()+140,4);if(!f||std::memcmp(h.data(),"SFRST001",8)||std::memcmp(h.data()+8,archdata::HASH,64)||std::memcmp(h.data()+72,selectedschema::HASH,64)||nf!=137||!nt||nt>64)throw std::runtime_error("Selected forest header");
  for(unsigned t=0;t<nt;++t){uint32_t n;f.read(reinterpret_cast<char*>(&n),4);if(!f||!n||n>=65536)throw std::runtime_error("Selected forest size");std::vector<ForestNode>tree(n);f.read(reinterpret_cast<char*>(tree.data()),n*16);if(!f)throw std::runtime_error("Selected forest body");for(unsigned i=0;i<n;++i){auto v=tree[i];if(!std::isfinite(v.number)||v.flags||(v.feature!=65535&&(v.feature>=137||v.left<=i||v.right<=i||v.left>=n||v.right>=n)))throw std::runtime_error("Selected forest node");}forest.push_back(std::move(tree));}if(f.peek()!=EOF)throw std::runtime_error("Selected forest trailer");
 }
 int cost(unsigned s,unsigned t,int dx,int dy)const{if(std::abs(dy)<96)return short_kernel.cost(s,t,dx,dy);return std::abs(dx)<=29?near_kernel.cost(s,t,dx,dy):far_kernel.cost(s,t,dx,dy);}
 int lower_bound(unsigned source,unsigned target,int dx,int dy)const{return terminal_bounds.lower(source,target,dx,dy);}
 void prepare(Node from,Node to,KernelRequest&r)const{initial.prepare(graph,from,to,r);}
 void prefetch(const KernelRequest&r)const{
  auto target=archdata::SITES[r.to/496];for(unsigned i=0;i<r.count;++i){auto b=r.branches[i];auto a=archdata::SITES[b.site];int dx=target.x-a.x,dy=target.y-a.y;auto one=[&](int x){if(std::abs(dy)<96)short_kernel.view(b.core,x,dy).prefetch();else if(std::abs(x)<=29)near_kernel.view(b.core,x,dy).prefetch();else far_kernel.view(b.core,x,dy).prefetch();};one(dx);if(std::min(a.x,target.x)<76&&std::max(a.x,target.x)>89)one(dx+(dx>0?-14:14));phi.prefetch_code(b.site,b.core);}for(auto e:initial.terminals[r.to%496])phi.prefetch_code(r.to/496,e.first);
 }
 void prefetch_phi_patterns(const KernelRequest&r)const{for(unsigned i=0;i<r.count;++i)phi.prefetch_pattern(r.branches[i].site,r.branches[i].core);for(auto e:initial.terminals[r.to%496])phi.prefetch_pattern(r.to/496,e.first);}
 int base(const KernelRequest&r,KernelTrace&trace)const{
  int best=r.local;trace={r.from/496,-1,-1,0,best,0,-1};auto target=archdata::SITES[r.to/496];unsigned tp=r.to%496;uint32_t mask=graph.reverse_vector_mask(r.to/496);
  struct Rank{unsigned i;int value;};std::array<Rank,32>ranking;for(unsigned i=0;i<r.count;++i){ranking[i]={i,0};if(RUNTIME_SOURCE_LOWER_PRUNE&&r.count>1){auto branch=r.branches[i];auto a=archdata::SITES[branch.site];int dx=target.x-a.x,dy=target.y-a.y;bool cross=std::min(a.x,target.x)<76&&std::max(a.x,target.x)>89,blocked=false;if(cross)for(auto b:archdata::BLOCKS)if(b.left==76&&b.right==89&&a.y>=b.lower&&a.y<=b.upper&&target.y>=b.lower&&target.y<=b.upper)blocked=true;int lb=blocked?1000000000:lower_bound(branch.core,tp,dx,dy);if(cross)lb=std::min(lb,lower_bound(branch.core,tp,dx+(dx>0?-14:14),dy)+292);ranking[i].value=lb+branch.entry+std::abs(xgap[a.x]-xgap[target.x])+std::abs(ygap[a.y]-ygap[target.y]);}}if(RUNTIME_SOURCE_LOWER_PRUNE&&r.count>1)std::sort(ranking.begin(),ranking.begin()+r.count,[](auto a,auto b){return a.value<b.value;});
  for(unsigned k=0;k<r.count;++k){if(RUNTIME_SOURCE_LOWER_PRUNE&&r.count>1&&ranking[k].value>best)break;auto branch=r.branches[ranking[k].i];auto a=archdata::SITES[branch.site];int dx=target.x-a.x,dy=target.y-a.y;bool cross=std::min(a.x,target.x)<76&&std::max(a.x,target.x)>89,blocked=false;if(cross)for(auto b:archdata::BLOCKS)if(b.left==76&&b.right==89&&a.y>=b.lower&&a.y<=b.upper&&target.y>=b.lower&&target.y<=b.upper)blocked=true;
   int nominal=1000000000,end=-1,arc=0,kind=0;unsigned selected_ordinal=256;auto evaluate=[&](const auto&normal,const auto&crossed){unsigned d=DirectionalTerminalBounds::direction(dx,dy);int normal_geo=DirectionalTerminalBounds::geometry(d,dx,dy),cross_geo=DirectionalTerminalBounds::geometry(d,dx+(dx>0?-14:14),dy);const auto*sorted=terminal_bounds.begin(branch.core,tp,d);for(unsigned j=0;j<terminal_bounds.size(tp);++j){auto b=sorted[j];int normal_lb=DirectionalTerminalBounds::ceil12(normal_geo+b.reduced),cross_lb=DirectionalTerminalBounds::ceil12(cross_geo+b.reduced)+292;if((blocked?cross_lb:normal_lb)>nominal)break;auto e=initial.terminals[tp][b.ordinal];if(!(mask&(1u<<archdata::NETS[e.first].vector))&&!(dx==0&&dy==0&&branch.core==e.first))continue;auto consider=[&](int value,int k){if(value<nominal||(value==nominal&&unsigned(b.ordinal)<selected_ordinal)){nominal=value;end=e.first;arc=e.second;kind=k;selected_ordinal=b.ordinal;}};if(!blocked&&normal_lb<=nominal)consider(normal.get(e.first)+int(e.second),0);if(cross&&cross_lb<=nominal)consider(crossed.get(e.first)+int(e.second)+292,2);}};
   if(std::abs(dy)<96){auto normal=short_kernel.view(branch.core,dx,dy);auto crossed=cross?short_kernel.view(branch.core,dx+(dx>0?-14:14),dy):normal;evaluate(normal,crossed);}else{auto one=[&](int x){return std::abs(x)<=29?near_kernel.view(branch.core,x,dy):far_kernel.view(branch.core,x,dy);};auto normal=one(dx),crossed=cross?one(dx+(dx>0?-14:14)):normal;evaluate(normal,crossed);}
   if(end<0)continue;int value=nominal+branch.entry+std::abs(xgap[a.x]-xgap[target.x])+std::abs(ygap[a.y]-ygap[target.y]);if(value<best||(value==best&&trace.core>=0&&branch.core<trace.core)){best=value;trace={branch.site,int(branch.core),end,branch.entry,nominal,arc,kind};}
  }
  if(best>=1000000000&&r.mask!=UINT32_MAX){KernelRequest all;initial.prepare(graph,r.from,r.to,all,true);return base(all,trace);}if(best>=1000000000)throw std::runtime_error("Unreachable runtime query");return best;
 }
 class Features{
  const RuntimeRouteModel&model;const KernelRequest&r;const KernelTrace&t;int b,sx,sy,tx,ty,ox,oy,sp,tp,dx,dy,ax,ay,qx,qy,gx,gy,direction,backward;bool valid,cross;std::array<float,137>cached;std::array<uint64_t,3>seen{};const int16_t*source_phi=nullptr,*target_phi=nullptr;
  static int sign(int x){return (x>0)-(x<0);}
  float phi_value(bool source,unsigned index){if(!valid)return 0;auto&ptr=source?source_phi:target_phi;if(!ptr)ptr=model.phi.row(source?t.site:r.to/496,source?t.core:t.end);return float(double(ptr[index])/12.0);}
  int response(unsigned j)const{if(!valid)return 0;int x=dx-(t.kind==2?sign(dx)*14:0),slope=dy<0?125:127,sg=dy<0?-1:1,ry=ay%12;auto query=[&](int q){return model.cost(t.core,t.end,x,sg*(q*12+ry))-q*slope;};if(j<6){const int periods[6]={0,2,8,20,32,45};return query(periods[j]);}int current=t.nominal-t.arc-(t.kind==2?292:0)-qy*slope;if(j==6)return qy?current-query(qy-1):0;return qy<45?query(qy+1)-current:0;}
  float calculate(unsigned i){if(i>=77&&i<101)return phi_value(true,i-77);if(i>=101&&i<125)return phi_value(false,i-101);if(i>=125){bool source=i<131;unsigned j=i-(source?125:131);return phi_value(source,(j/3)*12+(j%3)*4+(source?direction:backward));}if(i>=69)return response(i-69);if(i>=63){if(!valid)return 0;unsigned core=i<66?t.core:t.end,j=(i-63)%3;auto e=archdata::NETS[core];auto v=archdata::VECTORS[e.vector];return j==0?v.x:j==1?v.y:e.delay;}
   switch(i){case 0:return b;case 1:return sx;case 2:return sy;case 3:return tx;case 4:return ty;case 5:return ox;case 6:return oy;case 7:return sp;case 8:return tp;case 9:return selectedschema::PORT_TYPE[sp];case 10:return selectedschema::PORT_TYPE[tp];case 11:return selectedschema::PORT_LANE[sp];case 12:return selectedschema::PORT_LANE[tp];case 13:return t.core;case 14:return t.end;case 15:return valid?t.core%20:-1;case 16:return valid?t.end%20:-1;case 17:return valid?t.core/20:-1;case 18:return valid?t.end/20:-1;case 19:return dx;case 20:return dy;case 21:return ax;case 22:return ay;case 23:return qx;case 24:return qy;case 25:return sign(dx)*(ax-qx*10);case 26:return sign(dy)*(ay%12);case 27:return sx%10;case 28:return sy%12;case 29:return tx%10;case 30:return ty%12;case 31:return sy%100;case 32:return ty%100;case 33:return sy/100;case 34:return ty/100;case 35:return std::min(sx,119-sx);case 36:return std::min(tx,119-tx);case 37:return std::min(sy,549-sy);case 38:return std::min(ty,549-ty);case 39:return std::min(sy%100,99-sy%100);case 40:return std::min(ty%100,99-ty%100);case 41:return sx-ox;case 42:return sy-oy;case 43:return t.entry;case 44:return valid?t.nominal:b;case 45:return t.arc;case 46:return t.kind;case 47:return valid;case 48:return (valid?t.nominal:b)-125*qx-(dy>0?127:125)*qy;case 49:return valid?b-t.entry-t.nominal:0;case 50:return gx;case 51:return gy;case 52:return std::abs(gx);case 53:return std::abs(gy);case 54:return cross;case 55:return sx>=76&&sx<=89;case 56:return tx>=76&&tx<=89;case 57:{int n=0;for(int y=0;y<450;y+=100)n+=std::min(sy,ty)<y+49&&std::max(sy,ty)>y;return n;}case 58:return std::min(sx-75,90-sx);case 59:return std::min(tx-75,90-tx);case 60:return std::max(0,16-std::min(sx,tx));case 61:return std::max(0,100-std::min(sy,ty));case 62:return cross&&sy/100==ty/100&&sy%100<=49&&ty%100<=49;default:throw std::runtime_error("Feature index");}
  }
 public:
  Features(const RuntimeRouteModel&m,const KernelRequest&request,const KernelTrace&trace,int value):model(m),r(request),t(trace),b(value){auto a=archdata::SITES[t.site],target=archdata::SITES[r.to/496],original=archdata::SITES[r.from/496];sx=a.x;sy=a.y;tx=target.x;ty=target.y;ox=original.x;oy=original.y;sp=r.from%496;tp=r.to%496;dx=tx-sx;dy=ty-sy;ax=std::abs(dx);ay=std::abs(dy);qx=ax>29?(ax-20)/10:0;qy=ay/12;gx=m.xgap[tx]-m.xgap[sx];gy=m.ygap[ty]-m.ygap[sy];valid=t.core>=0;cross=std::min(sx,tx)<76&&std::max(sx,tx)>89;direction=(dx<0)*2+(dy<0);backward=(dx>=0)*2+(dy>=0);}
  float get(unsigned i){uint64_t bit=uint64_t(1)<<(i%64);if(!(seen[i/64]&bit)){cached[i]=calculate(i);seen[i/64]|=bit;}return cached[i];}
  std::array<float,137>dense(){for(unsigned i=0;i<137;++i)get(i);return cached;}
 };
 int correct(const KernelRequest&r,const KernelTrace&trace,int value,std::array<float,137>*features=nullptr)const{Features row(*this,r,trace,value);double correction=0;for(const auto&tree:forest){unsigned i=0;while(tree[i].feature!=65535){auto n=tree[i];i=double(row.get(n.feature))<=n.number?n.left:n.right;}correction+=tree[i].number;}if(features)*features=row.dense();return int(std::nearbyint(std::max(0.,double(value)+correction)));}
 int predict(const KernelRequest&r,KernelTrace*diagnostic=nullptr,std::array<float,137>*features=nullptr,int*baseline=nullptr)const{KernelTrace trace;int value=base(r,trace);if(diagnostic)*diagnostic=trace;if(baseline)*baseline=value;return correct(r,trace,value,features);}
};
